command:
set -euo pipefail; env_file="${UA_WHATBOX_ENV_FILE:-${XDG_CONFIG_HOME:-$HOME/.config}/upload-assistant/whatbox.env}"; set -a; source "$env_file"; set +a; export SSHPASS="$UA_WHATBOX_PASSWORD"; sshpass -e ssh -4 -o PubkeyAuthentication=no -o PreferredAuthentications=password -o StrictHostKeyChecking=yes artemisprime@destiny.whatbox.ca bash -s <<'REMOTE'
set -euo pipefail
podman exec upload-assistant-wastaken python3 - <<'PY'
import glob, os
port='3039'
inodes=[]
for path in ('/proc/net/tcp','/proc/net/tcp6'):
    try:
        for line in open(path):
            fields=line.split()
            if len(fields)>9 and fields[1].endswith(':'+port) and fields[3]=='0A':
                inodes.append(fields[9])
    except OSError as exc:
        print(f'{path}=unreadable:{type(exc).__name__}')
print('listener_inodes='+','.join(inodes))
for proc in glob.glob('/proc/[0-9]*'):
    pid=proc.rsplit('/',1)[-1]
    try:
        cmd=open(proc+'/cmdline','rb').read().replace(b'\0',b' ').decode(errors='replace').strip()
        fds=[]
        for fd in glob.glob(proc+'/fd/*'):
            try:
                target=os.readlink(fd)
                if any(f'socket:[{inode}]' in target for inode in inodes): fds.append(target)
            except OSError: pass
        if cmd and (fds or 'upload' in cmd.lower() or 'python' in cmd.lower()): print(f'pid={pid} fds={fds} cmd={cmd}')
    except OSError: pass
PY
REMOTE
